import{_ as e,o as s,c as t,ag as n}from"./chunks/framework.DoUXNnsN.js";const h=JSON.parse('{"title":"Git基础操作","description":"","frontmatter":{"title":"Git基础操作","aliases":["git init","git add","git commit","git status","git log","git diff",".gitignore","Git日常命令"],"tags":["工具与工程","Git"],"status":"ai-draft","sources":["https://git-scm.com/book/zh/v2/Git-基础-获取-Git-仓库","https://git-scm.com/docs/gitignore","基于模型知识"],"updated":"2026-10-21T00:00:00.000Z","order":2},"headers":[],"relativePath":"50-工具与工程/Git/Git基础操作.md","filePath":"50-工具与工程/Git/Git基础操作.md"}'),o={name:"50-工具与工程/Git/Git基础操作.md"};function i(d,a,c,p,l,r){return s(),t("div",null,[...a[0]||(a[0]=[n(`<blockquote><p>本篇是 <a href="/Encyclopedia/50-工具与工程/Git/Git">Git</a> 入门路径的第 2 篇。读完你应该能：在本地建仓库、提交改动、看懂 <code>status</code> 的每种状态、用 <code>diff</code> 比较改动、用 <code>log</code> 查历史，并写出自己的 <code>.gitignore</code>。</p><p>所有命令在 Windows 11 + Git for Windows 2.54.0（Git Bash）里实际运行。哈希值每次不同。为了版面整洁，输出里省略了 <code>LF will be replaced by CRLF</code> 警告（原因见 <a href="/Encyclopedia/50-工具与工程/Git/Git">Git</a>）。</p></blockquote><h2 id="一句话定义" tabindex="-1">一句话定义 <a class="header-anchor" href="#一句话定义" aria-label="Permalink to &quot;一句话定义&quot;">​</a></h2><p>Git 基础操作就是围绕&quot;三个区&quot;的一圈命令：<code>init</code> 建仓库，<code>add</code> 把改动放进暂存区，<code>commit</code> 存成快照，<code>status</code>/<code>diff</code>/<code>log</code> 观察当前状态和历史。</p><h2 id="先修知识" tabindex="-1">先修知识 <a class="header-anchor" href="#先修知识" aria-label="Permalink to &quot;先修知识&quot;">​</a></h2><ul><li><a href="/Encyclopedia/50-工具与工程/Git/Git">Git</a>：知道工作区、暂存区、仓库三个区，并配好了 <code>user.name</code> / <code>user.email</code>。</li><li><a href="/Encyclopedia/50-工具与工程/命令行与Linux">命令行与Linux</a>：会 <code>cd</code>、<code>ls</code>、<code>mkdir</code>。</li></ul><h2 id="它解决什么问题" tabindex="-1">它解决什么问题 <a class="header-anchor" href="#它解决什么问题" aria-label="Permalink to &quot;它解决什么问题&quot;">​</a></h2><p>你需要一套固定动作回答三个问题：&quot;我改了什么？&quot;（<code>status</code>、<code>diff</code>）&quot;把它记下来&quot;（<code>add</code> + <code>commit</code>）&quot;以前发生过什么？&quot;（<code>log</code>）。<code>.gitignore</code> 回答第四个：&quot;哪些文件根本不该进仓库？&quot;（编译产物、日志、密码文件）</p><h2 id="核心概念" tabindex="-1">核心概念 <a class="header-anchor" href="#核心概念" aria-label="Permalink to &quot;核心概念&quot;">​</a></h2><h3 id="文件的四种状态" tabindex="-1">文件的四种状态 <a class="header-anchor" href="#文件的四种状态" aria-label="Permalink to &quot;文件的四种状态&quot;">​</a></h3><table tabindex="0"><thead><tr><th>状态</th><th>含义</th><th><code>status -s</code> 显示</th></tr></thead><tbody><tr><td>Untracked</td><td>新文件，Git 还不认识</td><td><code>??</code></td></tr><tr><td>Modified</td><td>已被跟踪，但改了还没暂存</td><td>第二列 <code>M</code>（<code> M</code>）</td></tr><tr><td>Staged</td><td>已放入暂存区，等待提交</td><td>第一列 <code>M</code>/<code>A</code>（<code>M </code>、<code>A </code>）</td></tr><tr><td>Committed</td><td>已存入仓库，和工作区一致</td><td>不显示</td></tr></tbody></table><p>&quot;跟踪&quot;（tracked）指曾经 add 过或在上一次 commit 里的文件。<code>-s</code> 是 short 的缩写：两列字符，<strong>左列是暂存区相对仓库的变化，右列是工作区相对暂存区的变化</strong>。</p><h3 id="命令速览" tabindex="-1">命令速览 <a class="header-anchor" href="#命令速览" aria-label="Permalink to &quot;命令速览&quot;">​</a></h3><table tabindex="0"><thead><tr><th>命令</th><th>作用</th></tr></thead><tbody><tr><td><code>git init</code></td><td>在当前目录创建仓库（生成 <code>.git</code>）</td></tr><tr><td><code>git status</code></td><td>看三个区各有什么改动</td></tr><tr><td><code>git add 文件</code> / <code>git add .</code></td><td>放入暂存区（<code>.</code> 是当前目录下所有改动）</td></tr><tr><td><code>git commit -m &quot;说明&quot;</code></td><td>把暂存区存成一个 commit</td></tr><tr><td><code>git diff</code></td><td>工作区 vs 暂存区（还没 add 的改动）</td></tr><tr><td><code>git diff --staged</code></td><td>暂存区 vs 最近一次 commit（马上要提交的内容）</td></tr><tr><td><code>git log</code> / <code>git log --oneline</code></td><td>看提交历史</td></tr><tr><td><code>git show</code></td><td>看某个提交的详情</td></tr></tbody></table><h2 id="逐步例子" tabindex="-1">逐步例子 <a class="header-anchor" href="#逐步例子" aria-label="Permalink to &quot;逐步例子&quot;">​</a></h2><p>下面是一次完整的、连续的操作。每一步都标了&quot;此刻三个区的样子&quot;。</p><h3 id="第-1-步-建仓库、看状态" tabindex="-1">第 1 步：建仓库、看状态 <a class="header-anchor" href="#第-1-步-建仓库、看状态" aria-label="Permalink to &quot;第 1 步：建仓库、看状态&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ git init -b main</span></span>
<span class="line"><span>Initialized empty Git repository in .../lab/.git/</span></span>
<span class="line"><span>$ git config user.name &quot;Lab User&quot;</span></span>
<span class="line"><span>$ git config user.email &quot;lab@example.com&quot;</span></span>
<span class="line"><span>$ git status</span></span>
<span class="line"><span>On branch main</span></span>
<span class="line"><span></span></span>
<span class="line"><span>No commits yet</span></span>
<span class="line"><span></span></span>
<span class="line"><span>nothing to commit (create/copy files and use &quot;git add&quot; to track)</span></span></code></pre></div><p><code>-b main</code> 指定初始分支名。<code>No commits yet</code> = 还没有任何提交。</p><h3 id="第-2-步-新建文件-它是-untracked" tabindex="-1">第 2 步：新建文件，它是 Untracked <a class="header-anchor" href="#第-2-步-新建文件-它是-untracked" aria-label="Permalink to &quot;第 2 步：新建文件，它是 Untracked&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ echo &quot;hello git&quot; &gt; hello.txt</span></span>
<span class="line"><span>$ git status</span></span>
<span class="line"><span>On branch main</span></span>
<span class="line"><span></span></span>
<span class="line"><span>No commits yet</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Untracked files:</span></span>
<span class="line"><span>  (use &quot;git add &lt;file&gt;...&quot; to include in what will be committed)</span></span>
<span class="line"><span>	hello.txt</span></span>
<span class="line"><span></span></span>
<span class="line"><span>nothing added to commit but untracked files present (use &quot;git add&quot; to track)</span></span>
<span class="line"><span>$ git status -s</span></span>
<span class="line"><span>?? hello.txt</span></span></code></pre></div><p><code>status</code> 的括号里永远会提示下一步该用什么命令，养成读提示的习惯。</p><h3 id="第-3-步-add-进入暂存区" tabindex="-1">第 3 步：add，进入暂存区 <a class="header-anchor" href="#第-3-步-add-进入暂存区" aria-label="Permalink to &quot;第 3 步：add，进入暂存区&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ git add hello.txt</span></span>
<span class="line"><span>$ git status</span></span>
<span class="line"><span>On branch main</span></span>
<span class="line"><span></span></span>
<span class="line"><span>No commits yet</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Changes to be committed:</span></span>
<span class="line"><span>  (use &quot;git rm --cached &lt;file&gt;...&quot; to unstage)</span></span>
<span class="line"><span>	new file:   hello.txt</span></span></code></pre></div><h3 id="第-4-步-commit" tabindex="-1">第 4 步：commit <a class="header-anchor" href="#第-4-步-commit" aria-label="Permalink to &quot;第 4 步：commit&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ git commit -m &quot;add hello.txt&quot;</span></span>
<span class="line"><span>[main (root-commit) d951209] add hello.txt</span></span>
<span class="line"><span> 1 file changed, 1 insertion(+)</span></span>
<span class="line"><span> create mode 100644 hello.txt</span></span></code></pre></div><p>输出拆解：<code>main</code> 是当前分支；<code>root-commit</code> 表示第一个提交；<code>d951209</code> 是哈希前 7 位；<code>100644</code> 是普通文件的权限标记。再看历史：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ git log</span></span>
<span class="line"><span>commit d951209970c336d6a5bb6b2454b32c4b98ac1835</span></span>
<span class="line"><span>Author: Lab User &lt;lab@example.com&gt;</span></span>
<span class="line"><span>Date:   Wed Oct 21 20:01:38 2026 +0800</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    add hello.txt</span></span>
<span class="line"><span>$ git log --oneline</span></span>
<span class="line"><span>d951209 add hello.txt</span></span></code></pre></div><h3 id="第-5-步-改文件-用-diff-看区别" tabindex="-1">第 5 步：改文件，用 diff 看区别 <a class="header-anchor" href="#第-5-步-改文件-用-diff-看区别" aria-label="Permalink to &quot;第 5 步：改文件，用 diff 看区别&quot;">​</a></h3><p>给文件追加一行，然后比较：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ echo &quot;second line&quot; &gt;&gt; hello.txt</span></span>
<span class="line"><span>$ git diff</span></span>
<span class="line"><span>diff --git a/hello.txt b/hello.txt</span></span>
<span class="line"><span>index 8d0e412..ea111b3 100644</span></span>
<span class="line"><span>--- a/hello.txt</span></span>
<span class="line"><span>+++ b/hello.txt</span></span>
<span class="line"><span>@@ -1 +1,2 @@</span></span>
<span class="line"><span> hello git</span></span>
<span class="line"><span>+second line</span></span></code></pre></div><p>怎么读 diff：<code>---</code> 是旧版本，<code>+++</code> 是新版本；<code>@@ -1 +1,2 @@</code> 表示旧文件从第 1 行起共 1 行，新文件从第 1 行起共 2 行；以空格开头的行是没变的上下文，<code>+</code> 开头是新增，<code>-</code> 开头是删除。</p><p>现在 <code>git add</code>，再比较一次：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ git add hello.txt</span></span>
<span class="line"><span>$ git diff</span></span>
<span class="line"><span>$ git diff --staged</span></span>
<span class="line"><span>diff --git a/hello.txt b/hello.txt</span></span>
<span class="line"><span>index 8d0e412..ea111b3 100644</span></span>
<span class="line"><span>--- a/hello.txt</span></span>
<span class="line"><span>+++ b/hello.txt</span></span>
<span class="line"><span>@@ -1 +1,2 @@</span></span>
<span class="line"><span> hello git</span></span>
<span class="line"><span>+second line</span></span></code></pre></div><p>注意：add 之后 <code>git diff</code> <strong>什么都不输出</strong>（工作区和暂存区已一致），改动跑到了 <code>git diff --staged</code> 里。这是新手最常见的疑惑：&quot;我明明改了，diff 怎么没东西？&quot;——先看看是不是已经 add 了。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ git commit -m &quot;add second line&quot;</span></span>
<span class="line"><span>[main b11cc10] add second line</span></span>
<span class="line"><span> 1 file changed, 1 insertion(+)</span></span></code></pre></div><h3 id="第-6-步-gitignore" tabindex="-1">第 6 步：.gitignore <a class="header-anchor" href="#第-6-步-gitignore" aria-label="Permalink to &quot;第 6 步：.gitignore&quot;">​</a></h3><p>有些文件不该进仓库：编译输出（<code>bin/</code>、<code>obj/</code>、<code>build/</code>）、日志、本机配置、含密码的文件。在仓库根目录写一个 <code>.gitignore</code>，每行一条规则：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>a.log</span></span>
<span class="line"><span>build/</span></span></code></pre></div><p>模拟这个场景：创建 <code>a.log</code>、<code>build/o.bin</code>、<code>keep.txt</code> 和 <code>.gitignore</code> 后：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ git status -s</span></span>
<span class="line"><span>?? .gitignore</span></span>
<span class="line"><span>?? keep.txt</span></span></code></pre></div><p><code>a.log</code> 和 <code>build/</code> 根本没出现——被忽略了。可以问 Git &quot;是哪条规则忽略它的&quot;：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ git check-ignore -v a.log</span></span>
<span class="line"><span>.gitignore:1:a.log	a.log</span></span></code></pre></div><p>意思是：<code>.gitignore</code> 第 1 行的规则 <code>a.log</code> 匹配了 <code>a.log</code>。一次提交所有改动：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ git add .</span></span>
<span class="line"><span>$ git commit -m &quot;add gitignore and keep.txt&quot;</span></span>
<span class="line"><span>[main b9e5e96] add gitignore and keep.txt</span></span>
<span class="line"><span> 2 files changed, 3 insertions(+)</span></span>
<span class="line"><span> create mode 100644 .gitignore</span></span>
<span class="line"><span> create mode 100644 keep.txt</span></span>
<span class="line"><span>$ git ls-files</span></span>
<span class="line"><span>.gitignore</span></span>
<span class="line"><span>hello.txt</span></span>
<span class="line"><span>keep.txt</span></span></code></pre></div><p><code>git ls-files</code> 列出所有被跟踪的文件，<code>a.log</code> 和 <code>build/</code> 不在其中。再看带文件统计的历史：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ git log --oneline --stat</span></span>
<span class="line"><span>b9e5e96 add gitignore and keep.txt</span></span>
<span class="line"><span> .gitignore | 2 ++</span></span>
<span class="line"><span> keep.txt   | 1 +</span></span>
<span class="line"><span> 2 files changed, 3 insertions(+)</span></span>
<span class="line"><span>b11cc10 add second line</span></span>
<span class="line"><span> hello.txt | 1 +</span></span>
<span class="line"><span> 1 file changed, 1 insertion(+)</span></span>
<span class="line"><span>d951209 add hello.txt</span></span>
<span class="line"><span> hello.txt | 1 +</span></span>
<span class="line"><span> 1 file changed, 1 insertion(+)</span></span></code></pre></div><h3 id="gitignore-常用规则" tabindex="-1">.gitignore 常用规则 <a class="header-anchor" href="#gitignore-常用规则" aria-label="Permalink to &quot;.gitignore 常用规则&quot;">​</a></h3><table tabindex="0"><thead><tr><th>写法</th><th>含义</th></tr></thead><tbody><tr><td><code>*.log</code></td><td>所有 <code>.log</code> 文件</td></tr><tr><td><code>build/</code></td><td>名为 build 的目录</td></tr><tr><td><code>/secret.json</code></td><td>只忽略根目录下的 <code>secret.json</code></td></tr><tr><td><code>!important.log</code></td><td>例外：不忽略这个</td></tr><tr><td><code># 注释</code></td><td>注释行</td></tr></tbody></table><p>C# 项目最少应忽略 <code>bin/</code>、<code>obj/</code>、<code>.vs/</code>、<code>*.user</code>；密码文件如 <code>appsettings.Production.json</code>、<code>.env</code> 必须忽略。语法细节见官方文档 <a href="https://git-scm.com/docs/gitignore" target="_blank" rel="noreferrer">https://git-scm.com/docs/gitignore</a>。<strong>重要</strong>：<code>.gitignore</code> 只对&quot;还没被跟踪&quot;的文件有效，已经 commit 过的文件，之后写进 <code>.gitignore</code> 也不会自动从仓库消失；要用 <code>git rm --cached 文件</code> 取消跟踪（保留本地文件）。</p><h3 id="其它日常小命令" tabindex="-1">其它日常小命令 <a class="header-anchor" href="#其它日常小命令" aria-label="Permalink to &quot;其它日常小命令&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ git rm b.txt</span></span>
<span class="line"><span>rm &#39;b.txt&#39;</span></span>
<span class="line"><span>$ git mv a.txt alpha.txt</span></span>
<span class="line"><span>$ git status -s</span></span>
<span class="line"><span>R  a.txt -&gt; alpha.txt</span></span>
<span class="line"><span>D  b.txt</span></span></code></pre></div><p><code>git rm</code> 删除文件并把&quot;删除&quot;放进暂存区；<code>git mv</code> 重命名并暂存，Git 能识别为重命名（<code>R</code>）。直接在资源管理器里删/改名也行，之后 <code>git add -A</code> 效果一样。</p><h2 id="动手实验" tabindex="-1">动手实验 <a class="header-anchor" href="#动手实验" aria-label="Permalink to &quot;动手实验&quot;">​</a></h2><ol><li>建文件夹 <code>basic-lab</code>，<code>git init -b main</code>，配好本仓库的 user。</li><li>创建 <code>notes.txt</code>（写两行），<code>git status -s</code> 应显示 <code>?? notes.txt</code>。</li><li><code>git add notes.txt</code> 后 <code>git status -s</code> 应显示 <code>A notes.txt</code>，<code>git commit -m &quot;add notes&quot;</code>。</li><li>再追加一行，<code>git status -s</code> 应显示 <code> M notes.txt</code>（注意前面有空格，M 在右列）。<code>git diff</code> 应看到一行 <code>+</code>。</li><li><code>git add notes.txt</code>，<code>git status -s</code> 变成 <code>M notes.txt</code>（M 在左列），此时 <code>git diff</code> 无输出，<code>git diff --staged</code> 有输出。</li><li>创建 <code>temp.log</code>，写 <code>*.log</code> 进 <code>.gitignore</code>，确认 <code>git status -s</code> 里没有 <code>temp.log</code>，用 <code>git check-ignore -v temp.log</code> 验证。</li><li><code>git add .</code>、<code>git commit -m &quot;ignore logs&quot;</code>，<code>git log --oneline</code> 应有 3 条。</li></ol><h2 id="常见坑与排查" tabindex="-1">常见坑与排查 <a class="header-anchor" href="#常见坑与排查" aria-label="Permalink to &quot;常见坑与排查&quot;">​</a></h2><ul><li><strong><code>nothing to commit</code> 但你明明改了</strong>：看是不是改的文件被 <code>.gitignore</code> 忽略了，用 <code>git check-ignore -v 文件</code>。</li><li><strong>commit 时弹出编辑器（vim）</strong>：忘了 <code>-m</code>。在 vim 里按 <code>i</code> 输入说明，按 <code>Esc</code>，输入 <code>:wq</code> 回车保存退出；想放弃就 <code>:q!</code>。</li><li><strong>提交错文件</strong>：还没 push 的话，见 <a href="/Encyclopedia/50-工具与工程/Git/Git冲突与撤销">Git冲突与撤销</a> 的 <code>reset</code>/<code>amend</code>。</li><li><strong>把密码提交了</strong>：即使后面删掉，历史里仍然有。必须当作密码已泄露去更换，再清理历史（<code>git filter-repo</code> 等，超出入门范围）。</li><li><strong>空文件夹提交不了</strong>：Git 只跟踪文件。想保留空目录，放一个 <code>.gitkeep</code> 占位文件。</li><li><strong>PowerShell 里用 <code>&gt;</code> 创建的文件带 BOM</strong>：见 <a href="/Encyclopedia/50-工具与工程/Git/Git">Git</a> 动手实验的说明。</li></ul><h2 id="练习题与答案" tabindex="-1">练习题与答案 <a class="header-anchor" href="#练习题与答案" aria-label="Permalink to &quot;练习题与答案&quot;">​</a></h2><p><strong>1.</strong> 在 <code>status -s</code> 里看到 <code>MM a.txt</code> 是什么状态？ 答：左列 M：暂存区里有 a.txt 的改动；右列 M：暂存之后又改了工作区。同一个文件两处都有改动。</p><p><strong>2.</strong> 改了 5 个文件，只想提交其中 2 个，怎么做？ 答：<code>git add 文件1 文件2</code>，然后 <code>git commit</code>；其余 3 个保持在工作区。</p><p><strong>3.</strong> 如何看&quot;马上要提交的内容&quot;？ 答：<code>git diff --staged</code>（或 <code>--cached</code>，等价）。</p><p><strong>4.</strong> <code>.gitignore</code> 里写了 <code>config.json</code>，但 <code>git status</code> 还显示它被修改，为什么？ 答：因为它之前已被 commit 过，是已跟踪文件。要执行 <code>git rm --cached config.json</code> 并提交，之后才会被忽略。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>先 <code>add</code> 后 <code>commit</code>；<code>status</code> 随时看全貌，<code>diff</code> 看细节，<code>log</code> 看历史。</li><li><code>git diff</code> 看未暂存、<code>git diff --staged</code> 看已暂存。</li><li><code>.gitignore</code> 管&quot;不该进仓库&quot;的文件；密码类文件一定要忽略。</li></ul><h2 id="相关词条" tabindex="-1">相关词条 <a class="header-anchor" href="#相关词条" aria-label="Permalink to &quot;相关词条&quot;">​</a></h2><p><a href="/Encyclopedia/50-工具与工程/Git/Git">Git</a>、<a href="/Encyclopedia/50-工具与工程/Git/Git分支与合并">Git分支与合并</a>、<a href="/Encyclopedia/50-工具与工程/Git/Git远程仓库">Git远程仓库</a>、<a href="/Encyclopedia/50-工具与工程/Git/Git冲突与撤销">Git冲突与撤销</a>、<a href="/Encyclopedia/50-工具与工程/命令行与Linux">命令行与Linux</a>、<a href="/Encyclopedia/50-工具与工程/Markdown">Markdown</a></p><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h2><ul><li>Pro Git 第 2 章 Git 基础：<a href="https://git-scm.com/book/zh/v2/Git-%E5%9F%BA%E7%A1%80-%E8%8E%B7%E5%8F%96-Git-%E4%BB%93%E5%BA%93" target="_blank" rel="noreferrer">https://git-scm.com/book/zh/v2/Git-基础-获取-Git-仓库</a></li><li>gitignore 官方文档：<a href="https://git-scm.com/docs/gitignore" target="_blank" rel="noreferrer">https://git-scm.com/docs/gitignore</a></li></ul>`,67)])])}const u=e(o,[["render",i]]);export{h as __pageData,u as default};
